class SearchViewModel(
    private val savedStateHandle: SavedStateHandle
) : ViewModel() {
    val query = savedStateHandle.getStateFlow("query", "")
    fun updateQuery(value: String) { savedStateHandle["query"] = value }
}

class EditorViewModel(
    private val savedStateHandle: SavedStateHandle,
    private val drafts: DraftRepository
) : ViewModel() {
    private val draftId = savedStateHandle.get<String>("draftId")
        ?: drafts.createDraft().also { savedStateHandle["draftId"] = it }
}

@Composable
fun EditorScreen(viewModel: EditorViewModel) {
    var selectedTab by rememberSaveable { mutableIntStateOf(0) }
    val state by viewModel.state.collectAsStateWithLifecycle()
    EditorContent(state, selectedTab, onTabChange = { selectedTab = it })
}
